_OLD_NAMES = (
    tmpln.K1Q1_MCOM,
    tmpln.K1Q2_SR_BCOM,
    tmpln.K3Q3,
    tmpln.K1Q2_SR_QQK,
    tmpln.K1Q2_WR_KQQ,
    tmpln.K1Q2_UR_QQK,
    tmpln.K2Q1,
    tmpln.K2Q2,
    tmpln.K1Q2_SR_KQQ,
)


def _sug(name):
    return name[2:]


def _tmpl(name, *args):
    return wtp1.mktmpl([[name], *[[arg] for arg in args]])


def _minimal_cif2(*verse_body_items):
    return {
        "ws-chap-noinclude-header": "",
        "ws-chap-body": {
            "א": {
                "prefix": "",
                "location": "",
                "verse-body": list(verse_body_items),
            }
        },
        "ws-chap-good-ending": "",
        "ws-chap-noinclude-footer": "",
        "ws-chap-category": "",
    }


def _set_ctx(book39, he_chnu):
    mod._ctx["bk39id"] = book39
    mod._ctx["he_chnu"] = he_chnu
    mod._ctx["chapter"] = 1
    mod._ctx["he_vrnu"] = None
    mod._ctx["verse"] = None


class WsBotKukSpecialCallsiteMigrationTests(unittest.TestCase):
    def setUp(self):
        mod._warnings.clear()

    def test_rewrites_all_nine_deprecated_template_names(self):
        for old_name in _OLD_NAMES:
            with self.subTest(old_name=old_name):
                tmpl = _tmpl(old_name, "כְּתִיב", "קרי")

                out_tmpl = mod._transform_kuk_special_callsite(tmpl)[0]

                self.assertEqual(
                    ws_unparse.unparse(out_tmpl),
                    f'{{{{מ:כו"ק מיוחד|כְּתִיב|קרי|סוג={_sug(old_name)}}}}}',
                )

    def test_preserves_named_params_and_appends_sug(self):
        old_name = tmpln.K1Q2_SR_KQQ
        tmpl = _tmpl(old_name, "כְּתִיב", "קרי", "מקורות=ל", "רווח=לא")

        out_tmpl = mod._transform_kuk_special_callsite(tmpl)[0]

        self.assertEqual(
            ws_unparse.unparse(out_tmpl),
            (
                '{{מ:כו"ק מיוחד|כְּתִיב|קרי|מקורות=ל|רווח=לא|'
                f"סוג={_sug(old_name)}}}}}"
            ),
        )

    def test_preflight_blocks_rvach_yes(self):
        old_name = tmpln.K1Q2_SR_KQQ
        _set_ctx("Joshua", "א")
        cif2 = _minimal_cif2(_tmpl(old_name, "כְּתִיב", "קרי", "רווח=כן"))

        with self.assertRaises(SystemExit) as ctx:
            mod._assert_preflight_passes(cif2)

        self.assertIn("רווח=כן", str(ctx.exception))
        self.assertEqual(len(mod.get_warnings()), 1)
        self.assertEqual(mod.get_warnings()[0]["reason"], "rvach-yes-manual-review")

    def test_existing_matching_sug_is_preserved_without_duplication(self):
        old_name = tmpln.K2Q2
        tmpl = _tmpl(old_name, "כְּתִיב", "קרי", f"סוג={_sug(old_name)}")

        out_tmpl = mod._transform_kuk_special_callsite(tmpl)[0]
        out = ws_unparse.unparse(out_tmpl)

        self.assertEqual(out, f'{{{{מ:כו"ק מיוחד|כְּתִיב|קרי|סוג={_sug(old_name)}}}}}')
        self.assertEqual(out.count("|סוג="), 1)

    def test_dispatch_via_ws_bot_edit_kind(self):
        edits_ctx = wbe.load_edits(
            "in/mam-ws-bot-edits/issue-67-kuk-special-callsite-migration.json"
        )

        self.assertFalse(edits_ctx["is-chapter-targeted"])
        self.assertIn("global-page-transform", edits_ctx)
        self.assertIs(edits_ctx["get-warnings"], mod.get_warnings)


if __name__ == "__main__":
    unittest.main()
